// integrations (P6; p6-plan §2, §3 seam 21): connectors, integration runs, test adapters, imports (staging, validation, commit through the ImportTargetRegistry port), webhooks and outbound writes (slices A and B). integrations imports no domain module: each domain registers its import target at composition (server.ts), the AutomationActionRegistry pattern.
// Created by T-DG6-BE-A with stub route files; the owning tasks fill them (p6-plan §5.1).
import type { FastifyInstance } from "fastify";
import type { ModuleDeps, ModuleRegistration } from "../platform/index.ts";
import { registerIntegrationRoutes } from "./routes.ts";

/**
 * Wiring hook called by the composition root (server.ts). Every route file of the module registers here (T-DG6-BE-A
 * created them as stubs; p6-plan §5.1). The module reports "scaffold" until a route exists, then "active".
 */
export function registerIntegrationsModule(app: FastifyInstance, deps: ModuleDeps): ModuleRegistration {
  const routes = [...registerIntegrationRoutes(app, deps)];
  return Object.freeze({
    module: "integrations",
    status: routes.length > 0 ? "active" : "scaffold",
    deliversIn: "P6",
    routes: Object.freeze(routes),
  });
}
// integrations module suite (P6; T-DG6-BE-A created the module, p6-plan §3 seam 21). The owning tasks add their behaviour
// tests here and under test/integration/integrations/. Until then: the module wires every route file through its hook, and
// reports "scaffold" while no route exists (a route-free module promises no behaviour).
import { readdirSync } from "node:fs";
import Fastify from "fastify";
import { describe, expect, it } from "vitest";
import type { ModuleDeps } from "../platform/index.ts";
import { registerIntegrationsModule } from "./index.ts";

describe("integrations module (P6)", () => {
  it("registers through its hook and reports its registration", async () => {
    const app = Fastify({ logger: false });
    try {
      const registration = registerIntegrationsModule(app, {} as ModuleDeps);
      expect(registration.module).toBe("integrations");
      expect(registration.deliversIn).toBe("P6");
      expect(registration.status).toBe(registration.routes.length > 0 ? "active" : "scaffold");
    } finally {
      await app.close();
    }
  });

  it("has its route files in place (1 created by T-DG6-BE-A, p6-plan §5.1)", () => {
    const files = readdirSync(new URL(".", import.meta.url)).filter(
      (f) => f.endsWith(".ts") && !f.endsWith(".test.ts"),
    );
    expect(files.length - 1).toBeGreaterThanOrEqual(1);
  });
});
// P6 route-file stub (T-DG6-BE-A; p6-plan §5.1, p6-work-split §E/F.1): connectors and integration runs (slice B); then imports (BE-M) and webhooks and outbound writes (BE-N), sequentially.
// Owned and filled by task BE-L. Until then it registers nothing; its registration line already exists, so the
// owning task edits only this file (and its own tests, pending list and contract exercises).
import type { FastifyInstance } from "fastify";
import type { ModuleDeps } from "../platform/index.ts";

/** Registers this file's routes and returns them as "METHOD /path" (none until BE-L fills it). */
export function registerIntegrationRoutes(_app: FastifyInstance, _deps: ModuleDeps): string[] {
  return [];
}
