import { P6_PENDING_BE_K } from "./p6-pending-be-k.ts";

export const P6_PENDING_ARCH_02: readonly string[] = [
  ...P6_PENDING_BE_G,
  ...P6_PENDING_BE_H2,
  ...P6_PENDING_BE_I,
  ...P6_PENDING_BE_I2,
  ...P6_PENDING_BE_J,
  ...P6_PENDING_BE_K,
];
// P6 operations without a route yet, owned by backend-workflow-engineer task T-DG6-BE-K (slice J: operational exceptions and heartbeat; ADR-0053 §2, §6)
// (docs/architecture/p6-work-split.md §J/C). Remove an entry in the same change that registers its route and exercises it in
// the contract test. Must be empty when the DG6 candidate freezes. Only the owning task edits this file.
export const P6_PENDING_BE_K: readonly string[] = [
  "listOperationalExceptions",
  "getOperationalException",
  "acknowledgeOperationalException",
  "resolveOperationalException",
  "getWorkerHeartbeat",
];
// The operations the P6 contract adds (docs/api/openapi.yaml 1.5.0-p6 onward), one block per architecture task. Frozen
// per block (solution-architect); each later ARCH task appends its own block. Used to keep the P2-scoped generated sweeps
// (aud-write-deny.test.ts, kpi-aud-write-deny.test.ts) on their P2 scope, as p3-, p4- and p5-operations.ts do; the P6
// slices add their own AUD tests once their operations are routed (docs/architecture/p6-work-split.md §2 rule 7).

export const P6_OPERATION_IDS: ReadonlySet<string> = new Set([
  // T-DG6-ARCH-01: slices E and F (13 operations; ADR-0051, ADR-0052). Spelled out so the set does not shrink as the
  // pending lists empty.
  "getRecordSensitivity",
  "putRecordSensitivity",
  "listSensitiveGrants",
  "createSensitiveGrant",
  "getSensitiveGrant",
  "revokeSensitiveGrant",
  "resolveDeepLink",
  "previewEvidenceContent",
  "getUploadPolicy",
  "putUploadPolicy",
  "getSecurityRateLimits",
  "listAuditEvents",
  "getAuditEvent",
  // T-DG6-ARCH-02: slices J and C (17 operations; ADR-0053, ADR-0054).
  "listOperationalExceptions",
  "getOperationalException",
  "acknowledgeOperationalException",
  "resolveOperationalException",
  "getWorkerHeartbeat",
  "listServiceIdentities",
  "getServiceIdentity",
  "putServiceIdentity",
  "getIdentitySettings",
  "getStorageSetting",
  "putStorageSetting",
  "testStorageSetting",
  "listNotificationChannels",
  "getNotificationChannel",
  "putNotificationChannel",
  "testNotificationChannel",
  "listNotificationDeliveries",
]);
